// ==WorldTivi==
// @name        VTV.vn
// @version     1.0.0
// @match       https://vtv.vn/truyen-hinh-truc-tuyen/*
// @connect     vtv.vn, ovp.sohatv.vn
// ==/WorldTivi==

// Personal example (spec §10b): not for commercial builds. Only pages with a live player work (VTV1 today).
export async function resolve(url, ctx) {
  const page = (await ctx.fetch(url, { headers: { Referer: "https://vtv.vn/" } })).text();
  const embed = ctx.util.regex("https://ovp\\.sohatv\\.vn/embed\\?v=[A-Za-z0-9_-]+", page);
  if (!embed) throw new Error("no live player on this page");
  const html = (await ctx.fetch(embed[0], { headers: { Referer: "https://vtv.vn/" } })).text();
  const src = ctx.util.regex('"src"\\s*:\\s*"(https:[^"]+?\\.m3u8[^"]*)"', html);
  if (!src) throw new Error("no stream in the player");
  const link = src[1].replace(/\\\//g, "/");
  // Links look like https://cdn-live.vtv.vn/<token>/<expiry>/live/...: stay valid until the expiry.
  const exp = /\/(\d{10})\//.exec(link);
  const ttl = exp ? Math.max(60, Number(exp[1]) - Math.floor(Date.now() / 1000) - 300) : 600;
  return { streams: [{ url: link, label: "vtv.vn", quality: "1080p" }], ttl };
}

// ==WorldTivi==
// @name        VTVgo
// @version     1.2.0
// @match       https://vtvgo.vn/channel/*
// @match       worldtivi://vtvgo/*
// @connect     api.vtvdigital.org
// @guide
// @catchup     1
// ==/WorldTivi==

// Personal example (spec §10b): not for commercial builds.
const API = "https://api.vtvdigital.org";

function channelId(url) {
  const m = /\/channel\/([A-Za-z0-9_-]+)/.exec(url) || /^worldtivi:\/\/vtvgo\/([A-Za-z0-9_-]+)/.exec(url);
  if (!m) throw new Error("not a VTVgo channel: " + url);
  return m[1];
}

const HEADERS = { Origin: "https://vtvgo.vn", Referer: "https://vtvgo.vn/" };

// The free links of a playback/source answer: modes with isVip=0, sources without DRM; Akamai mirrors first.
function freeStreams(body) {
  if (!body.data) throw new Error((body.error && body.error.message) || "no data");
  const streams = [];
  let ttl = 4 * 3600;
  for (const mode of body.data.sourceModes || []) {
    if (mode.isVip) continue;
    for (const src of mode.multiSource || []) {
      const drm = src.drmInfo || {};
      if ((drm.drmType || "none") !== "none") continue;
      if (drm.expire) ttl = Math.min(ttl, drm.expire - 300);
      for (const s of src.sources || []) if (s.url) streams.push({ url: s.url, label: "VTVgo" });
    }
  }
  // Akamai mirrors first: they carry 1080p (the AWS one stops at 720p); their hdnts token only gates the master.
  streams.sort((a, b) => (b.url.includes(".akamaized.net/") ? 1 : 0) - (a.url.includes(".akamaized.net/") ? 1 : 0));
  return { streams, ttl };
}

export async function resolve(url, ctx) {
  const r = await ctx.fetch(API + "/live-channel/v21.0/playback/source", {
    json: { channelId: channelId(url), platform: "web" },
    headers: HEADERS,
  });
  const { streams, ttl } = freeStreams(r.json());
  // "https://vtvgo.vn/channel/3 | https://…/index.m3u8": direct links after the pipe are tried after VTVgo's own.
  url.split("|").slice(1).map((s) => s.trim()).filter((s) => /^https?:\/\//.test(s))
    .forEach((u, i) => streams.push({ url: u, label: "fallback " + (i + 1) }));
  return { streams, ttl };
}

// "Xem lại" as vtvgo.vn's web player does it (getCatchupSource): the same endpoint with the programme's start and
// end. VTVgo keeps 24 hours and only programmes that have ended; anonymous visitors get the free, DRM-free mode.
export async function catchup(url, startMs, endMs, ctx) {
  const iso = (ms) => new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z");
  const r = await ctx.fetch(API + "/live-channel/v21.0/playback/source", {
    json: { channelId: channelId(url), startTime: iso(startMs), endTime: iso(endMs), platform: "web" },
    headers: HEADERS,
  });
  return freeStreams(r.json());
}

// Yesterday (for catch-up), today and tomorrow (Vietnam time) for every channel in VTVgo's catalog, as tvg-id "vtvgo-<id>".
export async function guide(ctx) {
  const cat = (await ctx.fetch(API + "/display/v21.0/catalogs/with-channels", { headers: { Origin: "https://vtvgo.vn" } })).json();
  const ids = [];
  for (const g of cat.data || []) for (const c of g.channels || []) if (!ids.includes(c.id)) ids.push(c.id);
  const day = (offset) => new Date(Date.now() + 7 * 3600e3 + offset * 86400e3).toISOString().slice(0, 10);
  const out = [];
  for (let i = 0; i < ids.length; i += 20) {
    const chunk = ids.slice(i, i + 20).join(",");
    const r = (await ctx.fetch(API + "/display/v21.0/epg?channelIDs=" + encodeURIComponent(chunk) + "&from=" + day(-1) + "&to=" + day(1))).json();
    for (const [id, days] of Object.entries(r.data || {})) {
      for (const d of days || []) for (const p of d.programs || []) {
        out.push({ channel: "vtvgo-" + id, start: p.startTime, stop: p.endTime, title: p.title || "", desc: p.description || "" });
      }
    }
  }
  return out;
}

// ==WorldTivi==
// @name        xlivetv
// @version     1.0.1
// @description Live links of xlivetv.com / adult-tv-channels.click channel pages (personal config only)
// @match       https://xlivetv.com/*
// @match       https://adult-tv-channels.click/*
// @connect     xlivetv.com
// @connect     *.xlivetv.com
// @connect     adult-tv-channels.click
// ==/WorldTivi==

// Personal config only, never a public one. After the TV launcher's StreamProxy: read window.playerConfig in the
// channel page; "direct" gives sourceUrl, else POST apiUrl/endpoint whose fileUrl is base64 of the link written
// backwards, else fallbackUrl. The stream host answers 403 without the page's Referer, so the link carries it.

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// Like Python's b64decode: characters outside the alphabet are skipped.
function b64(s) {
  let bits = 0, n = 0, out = "";
  for (const ch of s) {
    const v = B64.indexOf(ch === "-" ? "+" : ch === "_" ? "/" : ch);
    if (v < 0) continue;
    bits = (bits << 6) | v;
    n += 6;
    if (n >= 8) {
      n -= 8;
      out += String.fromCharCode((bits >> n) & 0xff);
    }
  }
  return decodeURIComponent(escape(out));
}

// QuickJS has no URL class: origin and host by hand.
const originOf = (u) => (/^(https?:\/\/[^/?#]+)/.exec(u) || [])[1] || "";
const hostOf = (u) => originOf(u).replace(/^https?:\/\//, "").replace(/:\d+$/, "");

function config(html) {
  const m = /window\.playerConfig\s*=\s*\{([\s\S]*?)\};/.exec(html);
  if (!m) throw new Error("no playerConfig on page");
  const cfg = {};
  for (const f of m[1].matchAll(/(\w+)\s*:\s*"([^"]*)"/g)) cfg[f[1]] = f[2];
  return cfg;
}

export async function resolve(url, ctx) {
  const page = url.split("|")[0].trim();
  const origin = originOf(page);
  const headers = { Origin: origin, Referer: origin + "/" };
  const cfg = config((await ctx.fetch(page, { headers })).text());
  let link = cfg.streamType === "direct" ? cfg.sourceUrl : null;
  if (!link && cfg.apiUrl && cfg.endpoint) {
    try {
      const r = await ctx.fetch(cfg.apiUrl + "/" + cfg.endpoint, { method: "POST", body: "", headers });
      const enc = r.json().fileUrl;
      if (enc) link = b64(enc).split("").reverse().join("");
    } catch (e) {
      ctx.log && ctx.log("api failed (" + e.message + "), using fallbackUrl");
    }
  }
  link = link || cfg.fallbackUrl;
  if (!link) throw new Error("no stream in playerConfig");
  // The stream host wants its own site as Referer (stream.xlivetv.com → https://xlivetv.com/), whichever page
  // gave the link; the page's origin as a second try.
  const host = hostOf(link).split(".");
  const site = "https://" + host.slice(-2).join(".");
  const streams = [{ url: link, headers: { Referer: site + "/", Origin: site }, label: "xlivetv" }];
  if (site !== origin) streams.push({ url: link, headers: { Referer: origin + "/", Origin: origin }, label: "xlivetv (page referer)" });
  return { streams, ttl: 600 };
}
